public int findMinimumWeightWalk(int N, int[][] edges) {
    if (N <= 0) return -1;

    // Initialize graph representation
    int[][] graph = new int[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            graph[i][j] = Integer.MAX_VALUE;
        }
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        graph[u][v] = Math.min(graph[u][v], w);
    }

    // Check if a walk exists that visits each vertex at least once
    boolean[] visited = new boolean[N];
    dfs(0, graph, visited);
    for (boolean v : visited) {
        if (!v) return -1;
    }

    // Calculate the minimum total weight of the walk
    int[] minWeight = new int[N];
    for (int i = 0; i < N; i++) {
        minWeight[i] = Integer.MAX_VALUE;
    }
    minWeight[0] = 0;

    for (int count = 0; count < N - 1; count++) {
        for (int u = 0; u < N; u++) {
            for (int v = 0; v < N; v++) {
                if (graph[u][v] != Integer.MAX_VALUE && minWeight[u] != Integer.MAX_VALUE) {
                    minWeight[v] = Math.min(minWeight[v], minWeight[u] + graph[u][v]);
                }
            }
        }
    }

    int totalWeight = 0;
    for (int weight : minWeight) {
        if (weight == Integer.MAX_VALUE) return -1;
        totalWeight += weight;
    }

    return totalWeight;
}

private void dfs(int node, int[][] graph, boolean[] visited) {
    visited[node] = true;
    for (int i = 0; i < graph.length; i++) {
        if (graph[node][i] != Integer.MAX_VALUE && !visited[i]) {
            dfs(i, graph, visited);
        }
    }
}
